<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pageTitle='Dashboard Owner';
$today=(float)dbq("SELECT COALESCE(SUM(total),0) FROM orders WHERE DATE(created_at)=CURDATE() AND status_pesanan<>'Dibatalkan' AND status_bayar='Lunas'")->fetchColumn();
$week=(float)dbq("SELECT COALESCE(SUM(total),0) FROM orders WHERE YEARWEEK(created_at,1)=YEARWEEK(CURDATE(),1) AND status_pesanan<>'Dibatalkan' AND status_bayar='Lunas'")->fetchColumn();
$month=(float)dbq("SELECT COALESCE(SUM(total),0) FROM orders WHERE YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE()) AND status_pesanan<>'Dibatalkan' AND status_bayar='Lunas'")->fetchColumn();
$ordersToday=(int)dbq('SELECT COUNT(*) FROM orders WHERE DATE(created_at)=CURDATE()')->fetchColumn();$pending=(int)dbq("SELECT COUNT(*) FROM moments WHERE status='pending'")->fetchColumn();$low=dbq('SELECT nama,stok FROM menus WHERE stok<=5 ORDER BY stok ASC LIMIT 5')->fetchAll();
$top=dbq("SELECT oi.nama_menu,SUM(oi.qty) qty FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) AND o.status_pesanan<>'Dibatalkan' GROUP BY oi.nama_menu ORDER BY qty DESC LIMIT 5")->fetchAll();
$daily=dbq("SELECT DATE(created_at) d,SUM(total) total FROM orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) AND status_bayar='Lunas' AND status_pesanan<>'Dibatalkan' GROUP BY DATE(created_at) ORDER BY d")->fetchAll();
$hours=dbq("SELECT HOUR(created_at) hr,COUNT(*) qty FROM orders WHERE created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) AND status_pesanan<>'Dibatalkan' GROUP BY HOUR(created_at) ORDER BY qty DESC LIMIT 8")->fetchAll();
$logs=dbq('SELECT l.*,u.nama FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 8')->fetchAll();
require __DIR__.'/../includes/admin-header.php'; ?>
<div class="flex flex-wrap items-center justify-between gap-3 mb-6"><div><p class="text-sm text-coffee/60">halo, <?= h(current_user()['nama']) ?> 👋</p><p class="text-xs text-coffee/50 mt-1">ringkasan operasional Kopiah hari ini.</p></div><a class="btn btn-coffee" href="<?= h(BASE_URL) ?>/admin/reports.php">Lihat Laporan →</a></div>
<div class="grid grid-cols-2 xl:grid-cols-4 gap-4"><div class="card p-5"><p class="text-xs text-coffee/55">Omzet hari ini</p><p class="font-serif text-2xl mt-2"><?= money($today) ?></p><p class="text-xs text-coffee/45 mt-2">pesanan lunas</p></div><div class="card p-5"><p class="text-xs text-coffee/55">Omzet minggu ini</p><p class="font-serif text-2xl mt-2"><?= money($week) ?></p><p class="text-xs text-coffee/45 mt-2">Senin–hari ini</p></div><div class="card p-5"><p class="text-xs text-coffee/55">Omzet bulan ini</p><p class="font-serif text-2xl mt-2"><?= money($month) ?></p><p class="text-xs text-coffee/45 mt-2"><?= date('F Y') ?></p></div><div class="card p-5"><p class="text-xs text-coffee/55">Pesanan hari ini</p><p class="font-serif text-2xl mt-2"><?= $ordersToday ?></p><p class="text-xs text-coffee/45 mt-2"><?= $pending ?> foto menunggu moderasi</p></div></div>
<div class="grid xl:grid-cols-3 gap-5 mt-5"><div class="card p-5 xl:col-span-2"><div class="flex justify-between items-center mb-4"><div><h2 class="font-serif text-xl">tren omzet</h2><p class="text-xs text-coffee/55 mt-1">7 hari terakhir, berdasarkan transaksi lunas</p></div></div><canvas id="salesChart" height="110" aria-label="Grafik omzet tujuh hari" role="img"></canvas></div><div class="card p-5"><h2 class="font-serif text-xl">menu terlaris</h2><p class="text-xs text-coffee/55 mt-1">30 hari terakhir</p><canvas id="topChart" height="210" class="mt-3"></canvas><?php if(!$top):?><p class="text-xs text-coffee/50 mt-3">belum ada data transaksi.</p><?php endif;?></div></div>
<div class="grid xl:grid-cols-2 gap-5 mt-5"><div class="card p-5"><h2 class="font-serif text-xl">jam ramai</h2><p class="text-xs text-coffee/55 mt-1">jumlah pesanan per jam, 30 hari terakhir</p><div class="mt-4 space-y-3"><?php $maxh=max(1,max(array_map(fn($x)=>(int)$x['qty'],$hours?:[['qty'=>1]])));foreach($hours as $hr):?><div><div class="flex justify-between text-xs mb-1"><span><?= str_pad((string)$hr['hr'],2,'0',STR_PAD_LEFT) ?>.00 WIB</span><b><?= (int)$hr['qty'] ?> pesanan</b></div><div class="h-2 bg-coffee/10 rounded-full overflow-hidden"><div class="h-full bg-sage rounded-full" style="width:<?= round((int)$hr['qty']/$maxh*100) ?>%"></div></div></div><?php endforeach;?><?php if(!$hours):?><p class="text-sm text-coffee/50">belum ada data.</p><?php endif;?></div></div><div class="card p-5"><h2 class="font-serif text-xl">stok menipis</h2><p class="text-xs text-coffee/55 mt-1">menu dengan stok 5 atau kurang</p><div class="mt-3 space-y-2"><?php foreach($low as $m):?><div class="flex items-center justify-between py-2 border-b border-coffee/10"><span class="text-sm"><?= h($m['nama']) ?></span><span class="status-pill <?= (int)$m['stok']===0?'status-red':'status-orange' ?>">stok <?= (int)$m['stok'] ?></span></div><?php endforeach;?><?php if(!$low):?><p class="text-sm text-coffee/50 mt-3">semua stok aman.</p><?php endif;?></div><a href="<?= h(BASE_URL) ?>/admin/menus.php" class="text-sm underline inline-block mt-4">Kelola menu &amp; stok</a></div></div>
<div class="card p-5 mt-5"><div class="flex justify-between items-center gap-4"><h2 class="font-serif text-xl">log aktivitas terakhir</h2><a class="text-sm underline" href="<?= h(BASE_URL) ?>/admin/settings.php#logs">lihat pengaturan/log</a></div><div class="table-wrap mt-3"><table class="admin-table"><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aksi</th><th>Detail</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td class="whitespace-nowrap"><?= h($l['created_at']) ?></td><td><?= h($l['nama']??'Sistem') ?></td><td><?= h($l['aksi']) ?></td><td><?= h($l['detail']) ?></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="4">belum ada aktivitas.</td></tr><?php endif;?></tbody></table></div></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>const sales=<?= json_encode(array_map(fn($d)=>['label'=>date('d M',strtotime($d['d'])),'total'=>(float)$d['total']],$daily),JSON_UNESCAPED_UNICODE) ?>;new Chart(document.getElementById('salesChart'),{type:'line',data:{labels:sales.map(x=>x.label),datasets:[{label:'Omzet',data:sales.map(x=>x.total),fill:true,tension:.35,borderWidth:2}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{callback:v=>'Rp'+Number(v).toLocaleString('id-ID')}}}}});const top=<?= json_encode(array_map(fn($d)=>['name'=>$d['nama_menu'],'qty'=>(int)$d['qty']],$top),JSON_UNESCAPED_UNICODE) ?>;new Chart(document.getElementById('topChart'),{type:'bar',data:{labels:top.map(x=>x.name),datasets:[{label:'Terjual',data:top.map(x=>x.qty),borderRadius:8}]},options:{indexAxis:'y',responsive:true,plugins:{legend:{display:false}},scales:{x:{beginAtZero:true}}}});</script>
